import type { Request, Response } from 'express';
import { sendEmail } from '../../email.js';

export default async function handler(req: Request, res: Response) {
  const { name, email, phone, service, message } = req.body as {
    name?: string;
    email?: string;
    phone?: string;
    service?: string;
    message?: string;
  };

  if (!name || !email || !message) {
    return res.status(400).json({ error: 'Name, email, and message are required.' });
  }

  const recipient = process.env.CONTACT_FORM_RECIPIENT_EMAIL;
  if (!recipient) {
    console.error('CONTACT_FORM_RECIPIENT_EMAIL is not set');
    return res.status(500).json({ error: 'Server configuration error.' });
  }

  const html = `
    <h2>New Contact Form Submission — Spotless Home</h2>
    <table style="border-collapse:collapse;font-family:sans-serif;font-size:14px;">
      <tr><td style="padding:6px 12px;font-weight:bold;color:#555;">Name</td><td style="padding:6px 12px;">${name}</td></tr>
      <tr><td style="padding:6px 12px;font-weight:bold;color:#555;">Email</td><td style="padding:6px 12px;"><a href="mailto:${email}">${email}</a></td></tr>
      ${phone ? `<tr><td style="padding:6px 12px;font-weight:bold;color:#555;">Phone</td><td style="padding:6px 12px;">${phone}</td></tr>` : ''}
      ${service ? `<tr><td style="padding:6px 12px;font-weight:bold;color:#555;">Service</td><td style="padding:6px 12px;">${service}</td></tr>` : ''}
      <tr><td style="padding:6px 12px;font-weight:bold;color:#555;vertical-align:top;">Message</td><td style="padding:6px 12px;">${message.replace(/\n/g, '<br>')}</td></tr>
    </table>
  `;

  const text = [
    'New Contact Form Submission — Spotless Home',
    '',
    `Name: ${name}`,
    `Email: ${email}`,
    phone ? `Phone: ${phone}` : '',
    service ? `Service: ${service}` : '',
    `Message:\n${message}`,
  ]
    .filter(Boolean)
    .join('\n');

  try {
    await sendEmail({
      to: recipient,
      replyTo: email,
      subject: `New inquiry from ${name} — Spotless Home`,
      html,
      text,
    });
    res.status(200).json({ ok: true });
  } catch (err) {
    console.error('contact form email failed', err);
    res.status(500).json({ error: 'Failed to send message. Please try again.' });
  }
}

